import { View, Text, StyleSheet } from "react-native";
import { createContext, useContext } from "react";
import { registerRootComponent } from "expo";

const UserContext = createContext({ name: "" });

function Header() {
  // энд бичнэ үү: UserContext-оос name-г ав
  const user = { name: "" };
  return <Text nativeID="hi" style={styles.hi}>Сайн уу, {user.name}!</Text>;
}

function App() {
  return (
    <UserContext.Provider value={{ name: "Ануужин" }}>
      <View style={styles.s}><Header /></View>
    </UserContext.Provider>
  );
}

const styles = StyleSheet.create({ s: { flex: 1, alignItems: "center", justifyContent: "center" }, hi: { fontSize: 20, fontWeight: "600" } });

registerRootComponent(App);

import { View, Text, StyleSheet } from "react-native";
import { createContext, useContext } from "react";
import { registerRootComponent } from "expo";

const UserContext = createContext({ name: "" });

function Header() {
  const user = useContext(UserContext);
  return <Text nativeID="hi" style={styles.hi}>Сайн уу, {user.name}!</Text>;
}

function App() {
  return (
    <UserContext.Provider value={{ name: "Ануужин" }}>
      <View style={styles.s}><Header /></View>
    </UserContext.Provider>
  );
}

const styles = StyleSheet.create({ s: { flex: 1, alignItems: "center", justifyContent: "center" }, hi: { fontSize: 20, fontWeight: "600" } });

registerRootComponent(App);
